#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,sys
from pathlib import Path
root,catalog,out=map(Path,sys.argv[1:4])
with catalog.open() as f:expected={r['path']:int(r['bytes']) for r in csv.DictReader(f,delimiter='\t')}
actual={p.relative_to(root).as_posix():len(p.read_bytes()) for p in root.rglob('*') if p.is_file()}
lines=['path\tissue\n']
for name in sorted(expected.keys() | actual.keys()):
    issue='extra' if name not in expected else 'missing' if name not in actual else 'size' if actual[name]!=expected[name] else ''
    if issue:lines.append(name+'\t'+issue+'\n')
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(''.join(lines))
PY
